# 포트와 어댑터 예시: Python 3에서 실행 가능한 코드
class Port:
    def send(self, msg): raise NotImplementedError
class ConsoleAdapter(Port):
    def send(self, msg): return f"sent {msg}"
print(ConsoleAdapter().send("hi"))

# 모듈러 모놀리스 예시: Python 3에서 실행 가능한 코드
modules = {"billing": [], "orders": [], "users": []}
print(sorted(modules))

# 인프라 레이어 예시: Python 3에서 실행 가능한 코드
db = {"order:1": {"total": 100}}
print(db["order:1"]["total"])

# 액티브 레코드 패턴 예시: Python 3에서 실행 가능한 코드
class User:
    table = {}
    def __init__(self, id, name): self.id=id; self.name=name
    def save(self): User.table[self.id]=self.name
u=User(1,"Kim"); u.save(); print(User.table)

# ORM 심화 예시: Python 3에서 실행 가능한 코드
user = {"id": 1, "posts": [10, 11]}
print(user["id"], len(user["posts"]))

# CQRS 구현 예시: Python 3에서 실행 가능한 코드
command_model = {"create_order": True}
read_model = {"order_count": 12}
print(read_model["order_count"])

# 스케줄링(cron) 예시: Python 3에서 실행 가능한 코드
schedule = {"minute": 0, "hour": 3, "job": "backup"}
print(schedule["job"])

# API 캐싱 전략 예시: Python 3에서 실행 가능한 코드
cache = {"GET /products": ["a", "b"]}
print(cache.get("GET /products"))

# HTTP 캐싱 예시: Python 3에서 실행 가능한 코드
headers = {"Cache-Control": "max-age=60"}
print(headers["Cache-Control"])

# 스트리밍 응답 예시: Python 3에서 실행 가능한 코드
for chunk in ["part1", "part2", "part3"]:
    print(chunk)

# 파일 업로드(멀티파트) 예시: Python 3에서 실행 가능한 코드
parts = {"field:name": "Kim", "file:avatar": b"PNG"}
print(list(parts))

# 알림 서비스 예시: Python 3에서 실행 가능한 코드
prefs = {"u1": ["push", "email"]}
for ch in prefs["u1"]:
    print(ch)

# 분산 설정 관리 예시: Python 3에서 실행 가능한 코드
config = {"feature_x": True, "timeout": 3}
print(config["timeout"])

# 피처 토글 예시: Python 3에서 실행 가능한 코드
toggles = {"new_ui": False}
print("new" if toggles["new_ui"] else "old")

# gRPC 개요 예시: Python 3에서 실행 가능한 코드
request = {"method": "GetUser", "id": 1}
response = {"name": "Kim"}
print(request["method"], response["name"])

# 프로토콜 버퍼(Protobuf) 예시: Python 3에서 실행 가능한 코드
schema = {"id": "int32", "name": "string"}
msg = {"id": 1, "name": "Kim"}
print(set(schema) == set(msg))

# 헬스 체크(gRPC) 예시: Python 3에서 실행 가능한 코드
status = {"serving": True}
print("SERVING" if status["serving"] else "NOT_SERVING")

# 헬스 엔드포인트 설계 예시: Python 3에서 실행 가능한 코드
health = {"status": "ok", "details": "hidden"}
public = {"status": health["status"]}
print(public)
